def handler(params):
    import json
    import re
    from datetime import date as calendar_date

    inputs = params.get("input", params)
    if not isinstance(inputs, dict):
        raise ValueError("INVALID_INPUT")
    options = inputs.get("options") or {}
    memory = inputs.get("conversationState") or {}
    history_status = "empty"
    if "history" in params:
        memory = {}
        history = params["history"]
        if history != [] and history is not None:
            history_status = "invalid"
            try:
                if not isinstance(history, list) or not isinstance(history[-1], dict):
                    raise ValueError("INVALID_HISTORY")
                # Only the latest final output can restore state, never an older turn or prose.
                output = history[-1].get("outputMessage")
                if not isinstance(output, str) or len(output) > 64000:
                    raise ValueError("INVALID_HISTORY_OUTPUT")
                output = json.loads(output)
                if isinstance(output, dict) and "conversationState" not in output and "res" in output:
                    output = output["res"]
                candidate = output.get("conversationState") if isinstance(output, dict) else None
                if not isinstance(candidate, dict) or not isinstance(candidate.get("scopeKey"), str) or not candidate["scopeKey"]:
                    raise ValueError("MISSING_HISTORY_STATE")
                keys = ("scopeKey", "businessType", "focusCurrencyCode", "baseDate", "comparedCurrencies")
                candidate = {key: candidate[key] for key in keys if key in candidate}
                if any(not isinstance(candidate.get(key, ""), str) for key in keys[:-1]):
                    raise ValueError("INVALID_HISTORY_STATE")
                if candidate.get("focusCurrencyCode", "") not in ("", "CNY", "USD", "HKD"):
                    raise ValueError("INVALID_HISTORY_CURRENCY")
                if candidate.get("businessType", "") not in ("", "自营贷款", "投资类资产", "同业资产", "定期存款", "同业负债"):
                    raise ValueError("INVALID_HISTORY_BUSINESS")
                compared_state = candidate.get("comparedCurrencies", [])
                if not isinstance(compared_state, list) or len(compared_state) not in (0, 2) or any(
                        c not in ("CNY", "USD", "HKD") for c in compared_state) or len(set(compared_state)) != len(compared_state):
                    raise ValueError("INVALID_HISTORY_COMPARISON")
                saved_base = candidate.get("baseDate", "")
                if saved_base and saved_base != "PREVIOUS" and calendar_date.fromisoformat(saved_base).isoformat() != saved_base:
                    raise ValueError("INVALID_HISTORY_BASE")
                memory = candidate
                history_status = "restored"
            except (ValueError, TypeError, KeyError, IndexError, RecursionError):
                memory = {}
    if not isinstance(options, dict) or not isinstance(memory, dict):
        raise ValueError("INVALID_CONTEXT_OBJECT")
    for key in ("orgCode", "currencyCode", "tenorCode", "asOfDate", "question", "frequency"):
        if inputs.get(key) is not None and not isinstance(inputs[key], str):
            raise ValueError("INVALID_INPUT_TYPE:" + key)
    for key in ("analysisMode", "baseDate", "businessType", "nodeCode", "focusCurrencyCode", "caliber", "metricCode"):
        if options.get(key) is not None and not isinstance(options[key], str):
            raise ValueError("INVALID_OPTION_TYPE:" + key)
    if memory.get("focusCurrencyCode") not in (None, "", "CNY", "USD", "HKD"):
        raise ValueError("INVALID_CONVERSATION_STATE")
    if memory.get("comparedCurrencies") is not None and not isinstance(memory["comparedCurrencies"], list):
        raise ValueError("INVALID_CONVERSATION_STATE")
    # Legacy flat arguments are accepted by the adapter, not required by the new start form.
    options = {**{k: inputs[k] for k in (
        "analysisMode", "baseDate", "businessType", "nodeCode", "focusCurrencyCode",
        "comparedCurrencies", "caliber", "metricCode", "dataNeeds",
    ) if inputs.get(k) is not None}, **options}
    metric = options.get("metricCode") or "REPRICING_GAP_RATIO"
    if metric != "REPRICING_GAP_RATIO":
        raise ValueError("UNSUPPORTED_METRIC")
    org = inputs.get("orgCode") or ""
    currency = inputs.get("currencyCode") or ""
    tenor = inputs.get("tenorCode") or ""
    date = inputs.get("asOfDate") or ""
    question = (inputs.get("question") or "").strip()
    frequency = inputs.get("frequency") or "MONTH"
    if not all((org, currency, tenor, date)):
        raise ValueError("MISSING_SCOPE")
    if org != "LEGAL" or tenor != "1Y":
        raise ValueError("UNSUPPORTED_SCOPE")
    if frequency not in ("MONTH", "DAY"):
        raise ValueError("UNSUPPORTED_FREQUENCY")
    try:
        if calendar_date.fromisoformat(date).isoformat() != date:
            raise ValueError("INVALID_DATE")
    except (TypeError, ValueError):
        raise ValueError("UNKNOWN_DATA_DATE")
    scope_key = "|".join((org, currency, tenor, date, frequency))
    if memory.get("scopeKey") and memory["scopeKey"] != scope_key:
        memory = {}
        history_status = "scope_changed"
    if history_status == "restored" and memory.get("baseDate", "") not in ("", "PREVIOUS") and memory["baseDate"] >= date:
        memory = {}
        history_status = "invalid"
    last_business = memory.get("businessType") or inputs.get("lastBusinessType") or ""
    last_focus = memory.get("focusCurrencyCode") or inputs.get("sessionFocusCurrencyCode")
    last_base = memory.get("baseDate") or inputs.get("lastBaseDate")
    last_compared = memory.get("comparedCurrencies") or inputs.get("lastComparedCurrencies") or []
    if isinstance(last_compared, dict):
        last_compared = last_compared.get("values") or []
    mentioned = []
    for token, code in (("人民币", "CNY"), ("美元", "USD"), ("港币", "HKD"),
                        ("港元", "HKD"), ("CNY", "CNY"), ("USD", "USD"), ("HKD", "HKD")):
        if token in question and code not in mentioned:
            mentioned.append(code)
    compared = options.get("comparedCurrencies")
    if isinstance(compared, dict):
        compared = compared.get("values")
    compared = compared or (mentioned if len(mentioned) == 2 else [])
    if compared and (not isinstance(compared, list) or len(compared) != 2 or
                     len(set(compared)) != 2 or any(c not in ("CNY", "USD", "HKD") for c in compared)):
        raise ValueError("TWO_CURRENCIES_REQUIRED")
    focus = currency if compared else (options.get("focusCurrencyCode") or
        (mentioned[0] if mentioned else None) or last_focus or currency)
    if currency not in ("CNY", "USD", "HKD") or focus not in ("CNY", "USD", "HKD"):
        raise ValueError("UNSUPPORTED_CURRENCY")
    ambiguous = bool(last_compared and not mentioned and not options.get("focusCurrencyCode")
        and not compared and any(w in question for w in ("它", "这个币种", "那个币种")))
    missing_reference = ("history" in params and not last_business and not last_focus and not mentioned and
        not options.get("businessType") and not options.get("focusCurrencyCode") and
        any(w in question for w in ("它", "这个币种", "那个币种", "这个业务", "这类业务", "刚才", "之前那个")))
    history_clarification = history_status == "invalid" or missing_reference
    parsed_base = ""
    if "去年末" in question:
        parsed_base = str(int(date[:4]) - 1) + "-12-31"
    elif "上一期" in question or "上期" in question:
        parsed_base = "PREVIOUS"
    else:
        match = re.search(r"(?:与|和|较|比)\s*(20\d{2})[-/](\d{1,2})[-/](\d{1,2})", question)
        if match:
            parsed_base = "%04d-%02d-%02d" % tuple(int(p) for p in match.groups())
    base = options.get("baseDate") or parsed_base or last_base or ""
    if base and base != "PREVIOUS":
        try:
            if calendar_date.fromisoformat(base).isoformat() != base or base >= date:
                raise ValueError("INVALID_BASE_DATE")
        except (TypeError, ValueError):
            raise ValueError("INVALID_BASE_DATE")
    modes = ("overview", "limit", "trend", "calculation", "attribution", "business",
             "methodology", "clarification", "currencyCompare")
    mode = (options.get("analysisMode") or "").strip()
    if mode and mode not in modes:
        raise ValueError("UNSUPPORTED_ANALYSIS_MODE")
    business_names = ("自营贷款", "投资类资产", "同业资产", "定期存款", "同业负债")
    if not mode:
        if not question:
            mode = "overview"
        elif compared:
            mode = "currencyCompare"
        elif last_business and any(w in question for w in ("它", "这个业务", "这类业务")):
            mode = "business"
        elif any(n in question for n in business_names) and any(
            w in question for w in ("为什么", "原因", "新增", "退出", "大额", "业务")
        ):
            mode = "business"
        elif any(w in question for w in ("限额", "超限", "空间", "预警")):
            mode = "limit"
        elif any(w in question for w in ("口径", "剔除", "不含", "定义")):
            mode = "methodology"
        elif any(w in question for w in ("怎么算", "计算过程", "分子", "分母", "构成", "公式")):
            mode = "calculation"
        elif any(w in question for w in ("归因", "导致", "变动原因", "影响因素", "啥原因",
                                        "什么原因", "怎么变", "咋变", "咋回事")) or (
            any(w in question for w in ("为什么", "为何", "为啥")) and
            any(w in question for w in ("上升", "下降", "上涨", "下跌", "涨", "跌", "变化", "变动", "不一样"))
        ):
            mode = "attribution"
        elif any(w in question for w in ("走势", "趋势", "波动", "近几个月")):
            mode = "trend"
        elif any(w in question for w in ("是多少", "多高", "现在多少", "当前多少")):
            mode = "overview"
        else:
            leftover = question.replace("重定价缺口率", "")
            filler = set(" ，,。？?！!的了吧呢啊呀请帮我看看一下现在目前请问哈怎么样咋样什么情况啥情况最近怎么样呢")
            mode = "overview" if not "".join(c for c in leftover if not c.isspace() and c not in filler) else "clarification"
    if ambiguous or history_clarification:
        mode = "clarification"
    # Keep one primary mode, but collect independent, explicit subquestions.
    detected = []
    if any(w in question for w in ("限额", "超限", "空间", "预警")):
        detected.append("limit")
    if any(w in question for w in ("走势", "趋势", "波动", "近几个月")):
        detected.append("trend")
    if any(w in question for w in ("归因", "导致", "变动原因", "影响因素", "啥原因", "什么原因")) or (
        any(w in question for w in ("为什么", "为何", "为啥")) and
        any(w in question for w in ("上升", "下降", "上涨", "下跌", "涨", "跌", "变化", "变动", "不一样"))
    ):
        detected.append("attribution")
    # A business-specific 'why' alone asks for evidence, not invented formal attribution.
    if mode == "business" and not any(w in question for w in ("归因", "缺口率", "指标")):
        detected = [d for d in detected if d != "attribution"]
    if any(n in question for n in business_names) and any(
        w in question for w in ("原因", "为什么", "新增", "退出", "大额", "业务", "明细")
    ):
        detected.append("business")
    if any(w in question for w in ("口径", "剔除", "不含", "定义")):
        detected.append("methodology")
    if any(w in question for w in ("怎么算", "计算过程", "构成", "公式")) or (
        any(w in question for w in ("分子", "分母")) and "methodology" not in detected
    ):
        detected.append("calculation")
    requested = options.get("dataNeeds")
    if requested is not None and (not isinstance(requested, list) or not requested or
            any(not isinstance(d, str) or d not in modes or d == "clarification" for d in requested)):
        raise ValueError("INVALID_DATA_NEEDS")
    needs = list(dict.fromkeys([mode] + (requested if requested is not None else detected)))
    if mode == "clarification":
        needs = []
    elif len(needs) > 4 and not params.get("prepareOnly"):
        raise ValueError("TOO_MANY_DATA_NEEDS")
    if "currencyCompare" in needs and not compared:
        raise ValueError("TWO_CURRENCIES_REQUIRED")
    business = options.get("businessType") or next((n for n in business_names if n in question), "") or last_business
    calculation_parts = [part for part in re.split(r"[，,。；;？?]|再", question) if any(
        word in part for word in ("怎么算", "计算过程", "构成", "公式", "分项", "展示", "给出"))]
    node_question = " ".join(calculation_parts) or question
    node = options.get("nodeCode") or ("DENOMINATOR" if "分母" in node_question or "总生息资产" in node_question
        else "ASSETS" if "资产端" in node_question else "LIABILITIES" if "负债端" in node_question
        else "GAP" if "缺口" in node_question or "分子" in node_question else "ROOT")
    if mode == "currencyCompare" and not compared:
        raise ValueError("TWO_CURRENCIES_REQUIRED")
    state = {"scopeKey": scope_key, "businessType": business or "", "focusCurrencyCode": focus,
             "baseDate": last_base or "", "comparedCurrencies": compared or (last_compared if not mentioned else [])}
    if mode == "clarification":
        state = {**memory, "scopeKey": scope_key}
    query = {
        "orgCode": org, "currencies": compared or [focus], "tenorCode": tenor,
        "asOfDate": date, "frequency": frequency, "analysisMode": mode, "dataNeeds": needs,
        "baseDate": base if any(d in needs for d in ("overview", "attribution", "business")) else "",
        "businessType": (business or "自营贷款") if "business" in needs else "",
        "nodeCode": node if "calculation" in needs else "",
    }
    context = {
        "analysisMode": mode, "question": question, "query": query,
        "conversationState": state, "clarifyReason": "history" if history_clarification else "currency" if ambiguous else "intent",
        "historyStatus": history_status,
        "caliber": options.get("caliber") or "DEFAULT",
        "needsData": mode != "clarification" and (options.get("caliber") or "DEFAULT") == "DEFAULT",
    }
    if params.get("prepareOnly"):
        context["needsClassification"] = bool(question) and not (
            ambiguous or history_clarification or context["caliber"] != "DEFAULT" or options.get("analysisMode") or requested is not None)
        context["classificationContext"] = {"lastBusinessType": last_business,
            "businessType": business, "comparedCurrencies": compared,
            "focusCurrencyCode": focus, "metricCode": metric}
        context["resolvedOptions"] = {"baseDate": base, "businessType": business, "nodeCode": node}
        context["confirmedState"] = dict(memory)
    return context

def handler(params):
    preparation = params["preparation"]
    return {key: value for key, value in preparation.items() if key not in (
        "needsClassification", "classificationContext", "resolvedOptions", "confirmedState")}

def handler(params):
    context = params["context"]
    query = context["query"]
    currency = query["currencies"][0]
    body = {"analysisMode": context["analysisMode"], "scope": {"metricCode": "REPRICING_GAP_RATIO", "orgCode": query["orgCode"],
        "currencyCode": currency, "tenorCode": query["tenorCode"], "asOfDate": query["asOfDate"],
        "frequency": query["frequency"], "caliber": context["caliber"]}, "dataVersion": "LOCAL-CONTEXT-v1"}
    if context["caliber"] != "DEFAULT":
        body.update(status="unsupported", reason="UNSUPPORTED_CALIBER", supportedCalibers=["DEFAULT"])
    else:
        body.update(status="needs_input", clarifyReason=context["clarifyReason"])
        messages = {"tooManyAnalyses": "本轮涉及的分析类型超过单次支持范围，请拆成多个问题。",
            "history": "无法从上一轮恢复明确的分析对象或比较条件，请重新说明币种、业务类别或比较日期。",
            "business": "请明确要查看哪类业务，再查询该业务的变化或明细。"}
        if context["clarifyReason"] in messages:
            body["message"] = messages[context["clarifyReason"]]
        if context["clarifyReason"] == "currency":
            body["currencyOptions"] = ["CNY", "USD", "HKD"]
        else:
            body["modeOptions"] = [{"code": c, "label": n} for c, n in (
                ("overview", "当前值与限额情况"), ("limit", "还剩多少限额空间"), ("trend", "近几个月的走势"),
                ("calculation", "这个比率怎么算出来的"), ("attribution", "为什么上升或下降"),
                ("business", "哪类业务带来的变化"), ("methodology", "口径与剔除项说明"))]
    return {"returnCode": "SUC0000", "body": body}

def handler(params):
    import json
    result = params.get("apiResponse") or {}
    if result.get("returnCode") != "SUC0000":
        raise ValueError(result.get("errorCode") or "ALM_API_FAILED")
    context = params.get("context")
    body = result.get("body") or {}
    actual = body.get("scope") or {}
    if context:
        query = context["query"]
        expected = {"metricCode": "REPRICING_GAP_RATIO", "orgCode": query["orgCode"],
            "currencyCode": query["currencies"][0],
            "tenorCode": query["tenorCode"], "asOfDate": query["asOfDate"],
            "frequency": query["frequency"], "caliber": context["caliber"]}
    else:
        expected = {k: params.get(k) for k in ("metricCode", "orgCode", "currencyCode", "tenorCode", "asOfDate")}
        expected["currencyCode"] = params.get("focusCurrencyCode") or expected["currencyCode"]
    for key, value in expected.items():
        if actual.get(key) != value:
            raise ValueError("SCOPE_MISMATCH_" + key)
    if context and body.get("analysisMode") != context["analysisMode"]:
        raise ValueError("SCOPE_MISMATCH_analysisMode")
    if context and body.get("status") == "available":
        needs = query.get("dataNeeds") or [context["analysisMode"]]
        if body.get("dataNeeds", [context["analysisMode"]]) != needs:
            raise ValueError("SCOPE_MISMATCH_dataNeeds")
        if len(needs) > 1:
            modules = body.get("analyses") or {}
            if not isinstance(modules, dict) or set(modules) != set(needs):
                raise ValueError("MISSING_REQUESTED_ANALYSIS")
            for need, module in modules.items():
                if not isinstance(module, dict):
                    raise ValueError("INVALID_ANALYSIS_MODULE")
                parts = module.get("byCurrency", [module])
                currencies = query["currencies"] if need != "currencyCompare" else [query["currencies"][0]]
                if not isinstance(parts, list) or len(parts) != len(currencies):
                    raise ValueError("SCOPE_MISMATCH_moduleCurrencies")
                for part, currency in zip(parts, currencies):
                    if not isinstance(part, dict) or part.get("status") not in ("available", "unavailable"):
                        raise ValueError("INVALID_ANALYSIS_MODULE")
                    part_scope = part.get("scope") or {}
                    for key, value in {**expected, "currencyCode": currency}.items():
                        if part_scope.get(key) != value:
                            raise ValueError("SCOPE_MISMATCH_module_" + key)
                    if part.get("actualDataDate") != query["asOfDate"]:
                        raise ValueError("SCOPE_MISMATCH_module_actualDataDate")
                    if (part.get("analysisMode") != need or not part.get("dataVersion") or not part.get("caliberVersion") or
                            part["dataVersion"] != body.get("dataVersion") or part["caliberVersion"] != body.get("caliberVersion")):
                        raise ValueError("INVALID_ANALYSIS_MODULE")
                    if need in ("overview", "attribution", "business") and part.get("status") == "available":
                        if part_scope.get("baseDate") != actual.get("baseDate"):
                            raise ValueError("SCOPE_MISMATCH_module_baseDate")
                    if need == "business" and part.get("status") == "available" and part.get("businessType") != query["businessType"]:
                        raise ValueError("SCOPE_MISMATCH_businessType")
                    if need == "calculation" and part.get("nodeCode") != query["nodeCode"]:
                        raise ValueError("SCOPE_MISMATCH_nodeCode")
                    if need == "currencyCompare" and part.get("comparedCurrencies") != query["currencies"]:
                        raise ValueError("SCOPE_MISMATCH_comparedCurrencies")
    if context and body.get("actualDataDate", actual.get("asOfDate")) != actual.get("asOfDate"):
        raise ValueError("SCOPE_MISMATCH_actualDataDate")
    if body.get("status") not in ("available", "needs_input", "unsupported", "unavailable"):
        raise ValueError("DATA_NOT_AVAILABLE")
    if len(json.dumps(body, ensure_ascii=False)) > 16000:
        raise ValueError("PACKAGE_TOO_LARGE")
    if body["status"] == "available" and (not body.get("dataVersion") or not body.get("caliberVersion")):
        raise ValueError("VERSION_MISSING")
    state = dict(context["conversationState"]) if context else {}
    if context and body["status"] == "available":
        query = context["query"]
        if query["baseDate"] and query["baseDate"] != "PREVIOUS" and actual.get("baseDate") != query["baseDate"]:
            raise ValueError("SCOPE_MISMATCH_baseDate")
        if any(d in query.get("dataNeeds", [context["analysisMode"]]) for d in ("overview", "attribution", "business")):
            state["baseDate"] = actual.get("baseDate") or ""
        if context["analysisMode"] == "currencyCompare" and "analyses" not in body:
            if body.get("comparedCurrencies") != query["currencies"]:
                raise ValueError("SCOPE_MISMATCH_comparedCurrencies")
        if context["analysisMode"] == "business" and "analyses" not in body and body.get("businessType") != query["businessType"]:
            raise ValueError("SCOPE_MISMATCH_businessType")
        if context["analysisMode"] == "calculation" and "analyses" not in body and body.get("nodeCode") != query["nodeCode"]:
            raise ValueError("SCOPE_MISMATCH_nodeCode")
    return {"resultPackage": body, "conversationState": state}

from __future__ import annotations

def handler(params):
    import re

    from typing import Any, Mapping

    _BRACKET_INDEX = re.compile(r"\[(\d+)\]")

    DEFAULT_PATH_ALIASES: dict[str, str] = {
        "scope.actualDataDate": "actualDataDate",
    }

    def to_dot_path(path: str) -> str:
        """``trend[0].value`` → ``trend.0.value``。"""
        return _BRACKET_INDEX.sub(r".\1", path)

    def _apply_aliases(path: str, aliases: Mapping[str, str]) -> str:
        aliased = aliases.get(path)
        return aliased if aliased else to_dot_path(path)

    def normalize_model_answer(answer: Any, *, path_aliases: Mapping[str, str] | None = None) -> Any:
        """整形模型答案：路径归一 + 把 section 内嵌的 numericRefs 上提。

        与 v2 的 ``normalize_model_answer`` 行为一致，**就地修改**并返回原对象。
        非 dict 原样返回（后续 schema 校验会报 INVALID_ANSWER_SCHEMA）。
        """
        if not isinstance(answer, dict):
            return answer
        aliases = DEFAULT_PATH_ALIASES if path_aliases is None else path_aliases

        refs = answer.get("numericRefs")
        if not isinstance(refs, list):
            refs = []

        sections = answer.get("sections")
        for section in sections if isinstance(sections, list) else []:
            if not isinstance(section, dict):
                continue
            if isinstance(section.get("citations"), list):
                section["citations"] = [
                    _apply_aliases(path, aliases) if isinstance(path, str) else path
                    for path in section["citations"]
                ]
            nested = section.pop("numericRefs", None)
            if isinstance(nested, list):
                refs.extend(nested)

        for ref in refs:
            if isinstance(ref, dict) and isinstance(ref.get("path"), str):
                ref["path"] = _apply_aliases(ref["path"], aliases)

        answer["numericRefs"] = refs
        return answer

    import re

    from typing import Any, Iterable, Sequence

    IDENTIFIER_KEYS: tuple[str, ...] = ("bucketLabel", "largestBucketLabel", "positionId")

    _DATE_PATTERNS = (
        r"\d{4}[-/]\d{1,2}(?:[-/]\d{1,2})?",
        r"\d{4}年\d{1,2}月(?:\d{1,2}日)?",
        r"\d{4}年[末初]",
        r"(?<!\d)\d{1,2}月",
    )

    _ALPHANUMERIC_ID = re.compile(r"\b[A-Za-z]+-\d+\b")

    _NUMBER = re.compile(r"(?<![A-Za-z0-9.])[-+]?\d+(?:\.\d+)?(?=$|[^A-Za-z0-9.]|(?:pp|bp)\b)")

    _THRESHOLD_PREFIX = re.compile(r"均(?:超|超过|高于|处于)$")

    _THRESHOLD_SUFFIX = re.compile(r"%(?:以上)?")

    _NEGATIVE_CUES_BEFORE = ("抵消", "拖累", "负向", "稀释", "下拉", "减弱")

    _NEGATIVE_CUES_AFTER = ("负向影响", "负向贡献", "抵消作用", "抵消效应", "稀释效应")

    _POSITIVE_CUE = "正向"

    COMPARED_PATHS = ("comparedCurrencies.0.ratio", "comparedCurrencies.1.ratio")

    def collect_identifier_keys(value: Any, keys: Sequence[str] = IDENTIFIER_KEYS) -> list[str]:
        """递归收集结果包里作为标识符的字符串（桶标签、头寸号等）。"""
        found: list[str] = []
        if isinstance(value, dict):
            for key, child in value.items():
                if key in keys and isinstance(child, str):
                    found.append(child)
                elif isinstance(child, (dict, list)):
                    found.extend(collect_identifier_keys(child, keys))
        elif isinstance(value, list):
            for child in value:
                found.extend(collect_identifier_keys(child, keys))
        return found

    def strip_non_measurements(text: str, cited_identifiers: Iterable[str] = ()) -> str:
        """剥掉日期标签与已引用标识符，只留下可能是度量值的数字。"""
        cleaned = text
        for pattern in _DATE_PATTERNS:
            cleaned = re.sub(pattern, "", cleaned)
        for identifier in sorted({item for item in cited_identifiers if item}, key=len, reverse=True):
            cleaned = cleaned.replace(identifier, "")
        cleaned = _ALPHANUMERIC_ID.sub("", cleaned)
        return cleaned.replace("−", "-").replace("－", "-")

    def _is_threshold_claim_supported(
        stated: float,
        following: str,
        compared: Any,
        cited_paths: frozenset[str],
    ) -> bool:
        """「两币种均超过 N%」只有在两条 ratio 都 > N 且都被引用时才算有据。"""
        if not isinstance(compared, list) or len(compared) != 2:
            return False
        if not all(isinstance(item, dict) and isinstance(item.get("ratio"), (int, float)) for item in compared):
            return False
        if not all(item["ratio"] > stated for item in compared):
            return False
        return set(COMPARED_PATHS).issubset(cited_paths)

    def find_unreferenced_numbers(
        texts: Iterable[str],
        *,
        source_values: Iterable[float],
        cited_identifiers: Iterable[str] = (),
        compared_currencies: Any = None,
        cited_paths: Iterable[str] = (),
    ) -> list[str]:
        """返回未引用数字的诊断码列表，空列表表示正文每个数字都有据。

        ``source_values`` 是 numericRefs 声明的数值集合；``cited_identifiers`` 是
        结果包里被引用、但本身不是度量值的字符串；``compared_currencies`` 与
        ``cited_paths`` 供比较型阈值语句做双边校验。
        """
        values = [value for value in source_values if isinstance(value, (int, float))]
        identifiers = list(cited_identifiers)
        paths = frozenset(cited_paths)
        problems: list[str] = []

        for raw_text in texts:
            cleaned = strip_non_measurements(raw_text, identifiers)
            for match in _NUMBER.finditer(cleaned):
                token = match.group()
                stated = float(token)
                decimals = len(token.split(".")[1]) if "." in token else 0
                preceding = re.split(r"[。；;，,\n]", cleaned[:match.start()])[-1][-25:]
                following = re.split(r"[。；;，,\n]", cleaned[match.end():])[0][:18]

                if _THRESHOLD_PREFIX.search(preceding) and _THRESHOLD_SUFFIX.match(following):
                    if _is_threshold_claim_supported(stated, following, compared_currencies, paths):
                        continue
                    problems.append(f"FALSE_CURRENCY_THRESHOLD:{token}")
                    continue

                if any(round(value, decimals) == stated for value in values):
                    continue

                # 负向措辞下的正数幅度：结果包里是负值，文案说"拖累 0.12 个百分点"合法。
                negative_magnitude = (
                    not token.startswith(("-", "+"))
                    and _POSITIVE_CUE not in preceding
                    and (
                        any(cue in preceding for cue in _NEGATIVE_CUES_BEFORE)
                        or any(cue in following for cue in _NEGATIVE_CUES_AFTER)
                    )
                    and any(round(abs(value), decimals) == stated for value in values if value < 0)
                )
                if negative_magnitude:
                    continue
                problems.append(f"UNREFERENCED_NUMBER:{token}")

        return problems

    import re

    from dataclasses import dataclass

    from typing import Callable, Iterable, Sequence

    CLAUSE_NEGATIONS = ("未", "不能", "不可", "不代表", "不存在", "并非", "没有", "无", "非")

    SENTENCE_NEGATIONS = ("不能", "不可", "无法", "并非", "不代表", "不得")

    _CLAUSE_MARKS = "。；，,\n"

    _SENTENCE_MARKS = "。；\n"

    @dataclass(frozen=True)
    class GuardContext:
        """语义门禁的输入：模式、结果包、拼好的正文。"""

        mode: str
        result: dict
        narrative: str

    def _context_before(text: str, index: int, marks: str) -> str:
        """回溯到最近一个边界标记之后的子串（即该子句/句子的开头部分）。"""
        starts = [text.rfind(mark, 0, index) for mark in marks]
        return text[max(starts) + 1:index]

    def _clause_before(text: str, index: int) -> str:
        return _context_before(text, index, _CLAUSE_MARKS)

    def _sentence_before(text: str, index: int) -> str:
        return _context_before(text, index, _SENTENCE_MARKS)

    def _asserts(term: str, narrative: str, negations: Sequence[str], *, scoped) -> bool:
        """某个断言词是否被**断言**（而非出现在否定句里）。"""
        for match in re.finditer(re.escape(term), narrative):
            if not any(word in scoped(narrative, match.start()) for word in negations):
                return True
        return False

    def _contains_any(narrative: str, words: Iterable[str]) -> bool:
        return any(word in narrative for word in words)

    TechnicalLeak = ("数据包", "数据版本", "口径版本", "系统返回状态", "SYNTHETIC", "DEMO-ONLY")

    FORECAST_OR_RISK_LINK = (
        "下月继续", "下个月继续", "将直接触发", "必然超限",
        "净利息收入", "流动性结构变化", "流动性风险",
    )

    CURRENCY_COMPARISON_FORBIDDEN = (
        "整体风险影响", "管理优先级", "敞口", "约束更严",
        "错配压力", "对全行", "对整体", "合规空间",
    )

    CONCENTRATION_CLAIMS = ("为主", "明显集中", "高度集中", "占主导", "主导期限")

    CAUSALITY_CLAIMS = ("利率变动对", "利率波动对", "即时影响", "重定价敏感性")

    SCALE_MISLABELS = ("贷款余额", "发放额", "资产占比")

    SCALE_NEGATIONS = ("非", "不是", "并非", "不等于")

    _CONTRADICTORY_SIGN = re.compile(r"正向(?:影响|贡献)[^。；，]*[-−]\d")

    _MANAGEMENT_LIMIT = re.compile(r"监管(?:限额|阈值|红线)")

    def _contradictory_impact_sign(ctx: GuardContext) -> bool:
        """说"正向影响"却带着负号——自相矛盾。"""
        return _CONTRADICTORY_SIGN.search(ctx.narrative) is not None

    def _management_limit_mislabeled(ctx: GuardContext) -> bool:
        """把内部限额说成监管限额/阈值/红线。"""
        return bool(ctx.result.get("limit")) and _MANAGEMENT_LIMIT.search(ctx.narrative) is not None

    def _awkward_limit_exceedance(ctx: GuardContext) -> bool:
        return "超出距离" in ctx.narrative

    def _technical_metadata_leak(ctx: GuardContext) -> bool:
        """把数据包/版本号/演示标记等内部信息写进给用户看的文案。"""
        return _contains_any(ctx.narrative, TechnicalLeak)

    def _unavailable_technical_advice(ctx: GuardContext) -> bool:
        """结果本身不可用时，不该给"去检查数据源配置"这类运维建议。"""
        if ctx.result.get("status") not in {"unsupported", "unavailable"}:
            return False
        return _contains_any(ctx.narrative, ("数据源配置", "接口配置", "系统提示", "检查数据源"))

    def _attribution_unavailable_overclaim(ctx: GuardContext) -> bool:
        """结果不可用时，不得声称给出了跨期变动。"""
        if ctx.result.get("status") not in {"unsupported", "unavailable"}:
            return False
        return _contains_any(ctx.narrative, ("无法展示当期相对基期的变动", "无法展示跨期变动"))

    def _unsupported_forecast_or_risk_link(ctx: GuardContext) -> bool:
        """预测与风险传导不是本工作流能支撑的结论。"""
        return _contains_any(ctx.narrative, FORECAST_OR_RISK_LINK)

    def _overview_causality_without_attribution(ctx: GuardContext) -> bool:
        """概览模式没有归因依据，不该出现因果表述。"""
        if ctx.mode != "overview":
            return False
        if (ctx.result.get("attribution") or {}).get("factors"):
            return False
        return _contains_any(ctx.narrative, ("资产端", "负债端", "主要受"))

    def _currency_comparison_overclaim(ctx: GuardContext) -> bool:
        """币种对比不得越界到风险/优先级判断。

        与集中度规则一样做**子句级否定感知**：v2 原实现是纯子串匹配，会把
        "不代表存在合规空间差异" 这种免责说明也判成越界。
        """
        if ctx.mode != "currencyCompare":
            return False
        for term in CURRENCY_COMPARISON_FORBIDDEN:
            if _asserts(term, ctx.narrative, CLAUSE_NEGATIONS, scoped=_clause_before):
                return True
        return False

    def _concentration_overclaim(ctx: GuardContext) -> bool:
        """集中度不足 50% 时不得断言"明显集中"——子句级否定感知。"""
        share = (ctx.result.get("summary") or {}).get("largestBucketSharePct")
        if share is None or share >= 50:
            return False
        for claim in CONCENTRATION_CLAIMS:
            if _asserts(claim, ctx.narrative, CLAUSE_NEGATIONS, scoped=_clause_before):
                return True
        return False

    def _distribution_causality_unsupported(ctx: GuardContext) -> bool:
        """不得由桶规模推断利率因果——句子级否定感知。"""
        for claim in CAUSALITY_CLAIMS:
            if _asserts(claim, ctx.narrative, SENTENCE_NEGATIONS, scoped=_sentence_before):
                return True
        return False

    def _denominator_direction_wrong(ctx: GuardContext) -> bool:
        """分母实际在上升，文案却说"总生息资产规模下降"。"""
        if ctx.mode != "attribution":
            return False
        denominator = next(
            (item for item in ctx.result.get("factors", []) if item.get("factorCode") == "denominator"),
            None,
        )
        if not denominator:
            return False
        rising = denominator.get("currentValue", 0) > denominator.get("baseValue", 0)
        return rising and "总生息资产规模下降" in ctx.narrative

    def _business_scale_mislabeled(ctx: GuardContext) -> bool:
        """重定价规模不是贷款余额/发放额——短距离否定感知。"""
        for claim in SCALE_MISLABELS:
            for match in re.finditer(re.escape(claim), ctx.narrative):
                window = ctx.narrative[max(0, match.start() - 4):match.start()]
                prefix = ctx.narrative[max(0, match.start() - 40):match.start()]
                enumerated_negation = re.search(
                    r"(?:不是|并非|不等于)(?:(?:贷款余额|发放额|资产占比)[或和、])+$", prefix)
                if not any(word in window for word in SCALE_NEGATIONS) and not enumerated_negation:
                    return True
        return False

    @dataclass(frozen=True)
    class SemanticRule:
        code: str
        why: str
        detect: Callable[[GuardContext], bool]
        modes: frozenset[str] | None = None

    RULES: tuple[SemanticRule, ...] = (
        SemanticRule("CONTRADICTORY_IMPACT_SIGN", "说正向影响却带负号", _contradictory_impact_sign),
        SemanticRule("MANAGEMENT_LIMIT_MISLABELED", "内部限额被说成监管限额", _management_limit_mislabeled),
        SemanticRule("AWKWARD_LIMIT_EXCEEDANCE", "『超出距离』语义不成立", _awkward_limit_exceedance),
        SemanticRule("TECHNICAL_METADATA_LEAK", "把数据包/版本/演示标记写进用户文案", _technical_metadata_leak),
        SemanticRule("UNAVAILABLE_RESULT_TECHNICAL_ADVICE", "结果不可用却给运维建议", _unavailable_technical_advice),
        SemanticRule("ATTRIBUTION_UNAVAILABLE_OVERCLAIM", "结果不可用却声称给了跨期变动", _attribution_unavailable_overclaim),
        SemanticRule("UNSUPPORTED_FORECAST_OR_RISK_LINK", "预测或风险传导超出可支撑范围", _unsupported_forecast_or_risk_link),
        SemanticRule("OVERVIEW_CAUSALITY_WITHOUT_ATTRIBUTION", "概览模式出现无依据的因果表述", _overview_causality_without_attribution),
        SemanticRule("CURRENCY_COMPARISON_OVERCLAIM", "币种对比越界到风险/优先级判断", _currency_comparison_overclaim),
        SemanticRule("DISTRIBUTION_CONCENTRATION_OVERCLAIM", "集中度不足却断言明显集中（子句级否定感知）", _concentration_overclaim),
        SemanticRule("DISTRIBUTION_CAUSALITY_UNSUPPORTED", "由桶规模推断利率因果（句子级否定感知）", _distribution_causality_unsupported),
        SemanticRule("DENOMINATOR_DIRECTION_WRONG", "分母在上升却说下降", _denominator_direction_wrong),
        SemanticRule("BUSINESS_REPRICING_SCALE_MISLABELED", "重定价规模被说成贷款余额/发放额", _business_scale_mislabeled),
    )

    RULE_WHY: dict[str, str] = {rule.code: rule.why for rule in RULES}

    def check_overclaims(ctx: GuardContext) -> list[str]:
        """返回越界表述的诊断码；空列表表示没有越界。"""
        return [rule.code for rule in RULES if rule.detect(ctx)]

    from typing import Any

    def _resolve_path(document: dict, path: str) -> Any:
        if not isinstance(path, str) or not path:
            raise KeyError("INVALID_PATH")
        value: Any = document
        for segment in path.split("."):
            if isinstance(value, dict):
                value = value[segment]
            elif isinstance(value, list) and segment.isdigit():
                value = value[int(segment)]
            else:
                raise KeyError(path)
        return value

    def validate_answer(answer: dict, result: dict, *, mode: str | None = None) -> list[str]:
        errors: list[str] = []
        if not isinstance(answer, dict) or not isinstance(answer.get("headline"), str):
            return ["INVALID_ANSWER_SCHEMA"]
        sections = answer.get("sections")
        if not isinstance(sections, list) or not sections:
            errors.append("MISSING_SECTIONS")
        else:
            for section in sections:
                if not isinstance(section, dict) or not isinstance(section.get("text"), str):
                    errors.append("INVALID_SECTION")
                    continue
                if not isinstance(section.get("citations"), list) or not section["citations"]:
                    errors.append("MISSING_CITATIONS")
                    continue
                for path in section["citations"]:
                    try:
                        _resolve_path(result, path)
                    except (KeyError, IndexError, TypeError):
                        errors.append(f"INVALID_CITATION:{path}")
        refs = answer.get("numericRefs")
        if not isinstance(refs, list):
            errors.append("INVALID_NUMERIC_REFS")
        else:
            for ref in refs:
                if not isinstance(ref, dict) or "path" not in ref or "value" not in ref:
                    errors.append("INVALID_NUMERIC_REF")
                    continue
                try:
                    actual = _resolve_path(result, ref["path"])
                except (KeyError, IndexError, TypeError):
                    errors.append(f"INVALID_NUMERIC_PATH:{ref['path']}")
                    continue
                if isinstance(actual, (int, float)) and isinstance(ref["value"], (int, float)):
                    if abs(actual - ref["value"]) > 1e-6:
                        errors.append(f"NUMERIC_MISMATCH:{ref['path']}")
                elif actual != ref["value"]:
                    errors.append(f"VALUE_MISMATCH:{ref['path']}")
        if isinstance(refs, list) and all(isinstance(item, dict) for item in refs):
            source_values = [item.get("value") for item in refs if isinstance(item.get("value"), (int, float))]
            cited_identifiers = []
            if isinstance(sections, list):
                for section in sections:
                    if not isinstance(section, dict) or not isinstance(section.get("citations"), list):
                        continue
                    for path in section["citations"]:
                        try:
                            value = _resolve_path(result, path)
                        except (KeyError, IndexError, TypeError):
                            continue
                        if isinstance(value, str) and any(char.isdigit() for char in value):
                            cited_identifiers.append(value)
            cited_identifiers.extend(collect_identifier_keys(result))
            texts = [answer.get("headline", "")]
            if isinstance(sections, list):
                texts.extend(item["text"] for item in sections
                             if isinstance(item, dict) and isinstance(item.get("text"), str))
            errors.extend(
                find_unreferenced_numbers(
                    texts,
                    source_values=source_values,
                    cited_identifiers=cited_identifiers,
                    compared_currencies=result.get("comparedCurrencies"),
                    cited_paths={item["path"] for item in refs if isinstance(item.get("path"), str)},
                )
            )
        if str(result.get("attributionMethod") or "").startswith("SYNTHETIC"):
            if "百分点" in answer.get("headline", ""):
                errors.append("ILLUSTRATIVE_IMPACT_IN_HEADLINE")
            if isinstance(sections, list):
                for section in sections:
                    if isinstance(section, dict) and "illustrativeImpactPctPoint" in section.get("citations", []):
                        if "演示" not in section.get("text", ""):
                            errors.append("ILLUSTRATIVE_IMPACT_UNLABELED")
        initial_causes = result.get("attribution") or {}
        if mode == "overview" and initial_causes.get("factors"):
            paths = {r.get("path") for r in refs if isinstance(r, dict)} if isinstance(refs, list) else set()
            if "attribution.changePctPoint" not in paths:
                errors.append("INITIAL_CAUSES_MISSING")
            cause_sections = [s for s in sections if isinstance(s, dict) and any(
                str(p).startswith("attribution.") for p in s.get("citations", []) or [])] if isinstance(sections, list) else []
            if not cause_sections:
                errors.append("INITIAL_CAUSES_MISSING")
            if str(initial_causes.get("method", "")).startswith("SYNTHETIC"):
                if any("演示" not in s.get("text", "") for s in cause_sections):
                    errors.append("DEMO_ATTRIBUTION_UNLABELED")
        if mode == "attribution" and str(result.get("method", "")).startswith("SYNTHETIC"):
            if isinstance(sections, list) and any(isinstance(s, dict) and "演示" not in s.get("text", "")
                    for s in sections if isinstance(s, dict) and isinstance(s.get("citations"), list) and
                        any(p in ("changePctPoint", "factors") or str(p).startswith("factors.") for p in s["citations"])):
                errors.append("DEMO_ATTRIBUTION_UNLABELED")
        modules = result.get("analyses")
        if isinstance(modules, dict):
            for need in result.get("dataNeeds", []):
                module = modules.get(need)
                if not isinstance(module, dict):
                    errors.append("MISSING_REQUESTED_ANALYSIS:" + str(need))
                    continue
                parts = module.get("byCurrency", [module])
                for index, part in enumerate(parts):
                    prefix = "analyses." + need + (".byCurrency." + str(index) if "byCurrency" in module else "") + "."
                    selected = [s for s in sections if isinstance(s, dict) and isinstance(s.get("citations"), list) and any(
                        isinstance(p, str) and p.startswith(prefix) for p in s["citations"])] if isinstance(sections, list) else []
                    if not selected:
                        errors.append("UNANSWERED_DATA_NEED:" + prefix[:-1])
                        continue
                    sub = {"headline": "", "sections": [{**s, "citations": [p[len(prefix):] for p in s["citations"]
                        if isinstance(p, str) and p.startswith(prefix)]} for s in selected],
                        "numericRefs": [{**r, "path": r["path"][len(prefix):]} for r in refs
                            if isinstance(r, dict) and isinstance(r.get("path"), str) and r["path"].startswith(prefix)] if isinstance(refs, list) else []}
                    errors.extend(prefix + error for error in validate_answer(sub, part, mode=need))
                    errors.extend(prefix + error for error in check_overclaims(
                        GuardContext(mode=need, result=part, narrative=answer.get("headline", ""))))
                    paths = {r["path"] for r in sub["numericRefs"]}
                    citations = {p for s in sub["sections"] for p in s["citations"]}
                    if part.get("status") == "available":
                        required = {
                            "limit": "current.value", "attribution": "changePctPoint",
                            "calculation": "node.value", "business": "changeAmount",
                        }.get(need)
                        missing = required is not None and required not in paths
                        if need == "trend":
                            missing = not any(p.startswith("trend.") and p.endswith(".value") for p in paths)
                        if need == "methodology":
                            missing = not (citations.intersection({"formula", "gapFormula", "exclusions"}) or
                                any(p.startswith("exclusions.") for p in citations))
                        if need == "currencyCompare":
                            missing = any("currencySummary." + str(i) + ".ratio" not in paths
                                for i in range(len(part.get("currencySummary", []))))
                        if need == "attribution":
                            missing = missing or not any(p.startswith("factors.") and p.endswith(".impactPctPoint") for p in paths)
                        if missing:
                            errors.append("INSUFFICIENT_ANALYSIS_EVIDENCE:" + prefix[:-1])
        # 语义越界门禁：数字有据不代表说法成立（"监管限额""美元风险更高"）。
        # 给了 mode 才检查——脱离模式的规则会把合法的免责说明也误杀。
        if mode is not None:
            narrative = "\n".join(
                [answer.get("headline", "")]
                + [item["text"] for item in (sections if isinstance(sections, list) else [])
                   if isinstance(item, dict) and isinstance(item.get("text"), str)]
            )
            errors.extend(check_overclaims(GuardContext(mode="compound" if modules else mode, result=result, narrative=narrative)))
        return errors

    import json
    raw = params.get("narrativeRaw")
    data = params.get("resultPackage") or {}
    mode = params.get("analysisMode")
    errors = []
    try:
        if not isinstance(raw, str):
            raise ValueError("INVALID_JSON")
        cleaned = raw.strip().removeprefix("```json").removesuffix("```").strip()
        answer = normalize_model_answer(json.loads(cleaned))
    except (TypeError, ValueError):
        answer = None
        errors.append("INVALID_JSON")
    if not isinstance(mode, str) or not mode:
        errors.append("MISSING_ANALYSIS_MODE")
    errors.extend(validate_answer(answer, data, mode=mode))
    retry = bool(params.get("isRetry"))
    return {
        "narrative": answer if not errors else None,
        "validationErrors": errors,
        "degradeFlags": ["LIVE_MODEL_OUTPUT_INVALID"] if errors and retry else [],
    }

from __future__ import annotations

def handler(params):
    import re

    from typing import Any, Mapping

    _BRACKET_INDEX = re.compile(r"\[(\d+)\]")

    DEFAULT_PATH_ALIASES: dict[str, str] = {
        "scope.actualDataDate": "actualDataDate",
    }

    def to_dot_path(path: str) -> str:
        """``trend[0].value`` → ``trend.0.value``。"""
        return _BRACKET_INDEX.sub(r".\1", path)

    def _apply_aliases(path: str, aliases: Mapping[str, str]) -> str:
        aliased = aliases.get(path)
        return aliased if aliased else to_dot_path(path)

    def normalize_model_answer(answer: Any, *, path_aliases: Mapping[str, str] | None = None) -> Any:
        """整形模型答案：路径归一 + 把 section 内嵌的 numericRefs 上提。

        与 v2 的 ``normalize_model_answer`` 行为一致，**就地修改**并返回原对象。
        非 dict 原样返回（后续 schema 校验会报 INVALID_ANSWER_SCHEMA）。
        """
        if not isinstance(answer, dict):
            return answer
        aliases = DEFAULT_PATH_ALIASES if path_aliases is None else path_aliases

        refs = answer.get("numericRefs")
        if not isinstance(refs, list):
            refs = []

        sections = answer.get("sections")
        for section in sections if isinstance(sections, list) else []:
            if not isinstance(section, dict):
                continue
            if isinstance(section.get("citations"), list):
                section["citations"] = [
                    _apply_aliases(path, aliases) if isinstance(path, str) else path
                    for path in section["citations"]
                ]
            nested = section.pop("numericRefs", None)
            if isinstance(nested, list):
                refs.extend(nested)

        for ref in refs:
            if isinstance(ref, dict) and isinstance(ref.get("path"), str):
                ref["path"] = _apply_aliases(ref["path"], aliases)

        answer["numericRefs"] = refs
        return answer

    import re

    from typing import Any, Iterable, Sequence

    IDENTIFIER_KEYS: tuple[str, ...] = ("bucketLabel", "largestBucketLabel", "positionId")

    _DATE_PATTERNS = (
        r"\d{4}[-/]\d{1,2}(?:[-/]\d{1,2})?",
        r"\d{4}年\d{1,2}月(?:\d{1,2}日)?",
        r"\d{4}年[末初]",
        r"(?<!\d)\d{1,2}月",
    )

    _ALPHANUMERIC_ID = re.compile(r"\b[A-Za-z]+-\d+\b")

    _NUMBER = re.compile(r"(?<![A-Za-z0-9.])[-+]?\d+(?:\.\d+)?(?=$|[^A-Za-z0-9.]|(?:pp|bp)\b)")

    _THRESHOLD_PREFIX = re.compile(r"均(?:超|超过|高于|处于)$")

    _THRESHOLD_SUFFIX = re.compile(r"%(?:以上)?")

    _NEGATIVE_CUES_BEFORE = ("抵消", "拖累", "负向", "稀释", "下拉", "减弱")

    _NEGATIVE_CUES_AFTER = ("负向影响", "负向贡献", "抵消作用", "抵消效应", "稀释效应")

    _POSITIVE_CUE = "正向"

    COMPARED_PATHS = ("comparedCurrencies.0.ratio", "comparedCurrencies.1.ratio")

    def collect_identifier_keys(value: Any, keys: Sequence[str] = IDENTIFIER_KEYS) -> list[str]:
        """递归收集结果包里作为标识符的字符串（桶标签、头寸号等）。"""
        found: list[str] = []
        if isinstance(value, dict):
            for key, child in value.items():
                if key in keys and isinstance(child, str):
                    found.append(child)
                elif isinstance(child, (dict, list)):
                    found.extend(collect_identifier_keys(child, keys))
        elif isinstance(value, list):
            for child in value:
                found.extend(collect_identifier_keys(child, keys))
        return found

    def strip_non_measurements(text: str, cited_identifiers: Iterable[str] = ()) -> str:
        """剥掉日期标签与已引用标识符，只留下可能是度量值的数字。"""
        cleaned = text
        for pattern in _DATE_PATTERNS:
            cleaned = re.sub(pattern, "", cleaned)
        for identifier in sorted({item for item in cited_identifiers if item}, key=len, reverse=True):
            cleaned = cleaned.replace(identifier, "")
        cleaned = _ALPHANUMERIC_ID.sub("", cleaned)
        return cleaned.replace("−", "-").replace("－", "-")

    def _is_threshold_claim_supported(
        stated: float,
        following: str,
        compared: Any,
        cited_paths: frozenset[str],
    ) -> bool:
        """「两币种均超过 N%」只有在两条 ratio 都 > N 且都被引用时才算有据。"""
        if not isinstance(compared, list) or len(compared) != 2:
            return False
        if not all(isinstance(item, dict) and isinstance(item.get("ratio"), (int, float)) for item in compared):
            return False
        if not all(item["ratio"] > stated for item in compared):
            return False
        return set(COMPARED_PATHS).issubset(cited_paths)

    def find_unreferenced_numbers(
        texts: Iterable[str],
        *,
        source_values: Iterable[float],
        cited_identifiers: Iterable[str] = (),
        compared_currencies: Any = None,
        cited_paths: Iterable[str] = (),
    ) -> list[str]:
        """返回未引用数字的诊断码列表，空列表表示正文每个数字都有据。

        ``source_values`` 是 numericRefs 声明的数值集合；``cited_identifiers`` 是
        结果包里被引用、但本身不是度量值的字符串；``compared_currencies`` 与
        ``cited_paths`` 供比较型阈值语句做双边校验。
        """
        values = [value for value in source_values if isinstance(value, (int, float))]
        identifiers = list(cited_identifiers)
        paths = frozenset(cited_paths)
        problems: list[str] = []

        for raw_text in texts:
            cleaned = strip_non_measurements(raw_text, identifiers)
            for match in _NUMBER.finditer(cleaned):
                token = match.group()
                stated = float(token)
                decimals = len(token.split(".")[1]) if "." in token else 0
                preceding = re.split(r"[。；;，,\n]", cleaned[:match.start()])[-1][-25:]
                following = re.split(r"[。；;，,\n]", cleaned[match.end():])[0][:18]

                if _THRESHOLD_PREFIX.search(preceding) and _THRESHOLD_SUFFIX.match(following):
                    if _is_threshold_claim_supported(stated, following, compared_currencies, paths):
                        continue
                    problems.append(f"FALSE_CURRENCY_THRESHOLD:{token}")
                    continue

                if any(round(value, decimals) == stated for value in values):
                    continue

                # 负向措辞下的正数幅度：结果包里是负值，文案说"拖累 0.12 个百分点"合法。
                negative_magnitude = (
                    not token.startswith(("-", "+"))
                    and _POSITIVE_CUE not in preceding
                    and (
                        any(cue in preceding for cue in _NEGATIVE_CUES_BEFORE)
                        or any(cue in following for cue in _NEGATIVE_CUES_AFTER)
                    )
                    and any(round(abs(value), decimals) == stated for value in values if value < 0)
                )
                if negative_magnitude:
                    continue
                problems.append(f"UNREFERENCED_NUMBER:{token}")

        return problems

    import re

    from dataclasses import dataclass

    from typing import Callable, Iterable, Sequence

    CLAUSE_NEGATIONS = ("未", "不能", "不可", "不代表", "不存在", "并非", "没有", "无", "非")

    SENTENCE_NEGATIONS = ("不能", "不可", "无法", "并非", "不代表", "不得")

    _CLAUSE_MARKS = "。；，,\n"

    _SENTENCE_MARKS = "。；\n"

    @dataclass(frozen=True)
    class GuardContext:
        """语义门禁的输入：模式、结果包、拼好的正文。"""

        mode: str
        result: dict
        narrative: str

    def _context_before(text: str, index: int, marks: str) -> str:
        """回溯到最近一个边界标记之后的子串（即该子句/句子的开头部分）。"""
        starts = [text.rfind(mark, 0, index) for mark in marks]
        return text[max(starts) + 1:index]

    def _clause_before(text: str, index: int) -> str:
        return _context_before(text, index, _CLAUSE_MARKS)

    def _sentence_before(text: str, index: int) -> str:
        return _context_before(text, index, _SENTENCE_MARKS)

    def _asserts(term: str, narrative: str, negations: Sequence[str], *, scoped) -> bool:
        """某个断言词是否被**断言**（而非出现在否定句里）。"""
        for match in re.finditer(re.escape(term), narrative):
            if not any(word in scoped(narrative, match.start()) for word in negations):
                return True
        return False

    def _contains_any(narrative: str, words: Iterable[str]) -> bool:
        return any(word in narrative for word in words)

    TechnicalLeak = ("数据包", "数据版本", "口径版本", "系统返回状态", "SYNTHETIC", "DEMO-ONLY")

    FORECAST_OR_RISK_LINK = (
        "下月继续", "下个月继续", "将直接触发", "必然超限",
        "净利息收入", "流动性结构变化", "流动性风险",
    )

    CURRENCY_COMPARISON_FORBIDDEN = (
        "整体风险影响", "管理优先级", "敞口", "约束更严",
        "错配压力", "对全行", "对整体", "合规空间",
    )

    CONCENTRATION_CLAIMS = ("为主", "明显集中", "高度集中", "占主导", "主导期限")

    CAUSALITY_CLAIMS = ("利率变动对", "利率波动对", "即时影响", "重定价敏感性")

    SCALE_MISLABELS = ("贷款余额", "发放额", "资产占比")

    SCALE_NEGATIONS = ("非", "不是", "并非", "不等于")

    _CONTRADICTORY_SIGN = re.compile(r"正向(?:影响|贡献)[^。；，]*[-−]\d")

    _MANAGEMENT_LIMIT = re.compile(r"监管(?:限额|阈值|红线)")

    def _contradictory_impact_sign(ctx: GuardContext) -> bool:
        """说"正向影响"却带着负号——自相矛盾。"""
        return _CONTRADICTORY_SIGN.search(ctx.narrative) is not None

    def _management_limit_mislabeled(ctx: GuardContext) -> bool:
        """把内部限额说成监管限额/阈值/红线。"""
        return bool(ctx.result.get("limit")) and _MANAGEMENT_LIMIT.search(ctx.narrative) is not None

    def _awkward_limit_exceedance(ctx: GuardContext) -> bool:
        return "超出距离" in ctx.narrative

    def _technical_metadata_leak(ctx: GuardContext) -> bool:
        """把数据包/版本号/演示标记等内部信息写进给用户看的文案。"""
        return _contains_any(ctx.narrative, TechnicalLeak)

    def _unavailable_technical_advice(ctx: GuardContext) -> bool:
        """结果本身不可用时，不该给"去检查数据源配置"这类运维建议。"""
        if ctx.result.get("status") not in {"unsupported", "unavailable"}:
            return False
        return _contains_any(ctx.narrative, ("数据源配置", "接口配置", "系统提示", "检查数据源"))

    def _attribution_unavailable_overclaim(ctx: GuardContext) -> bool:
        """结果不可用时，不得声称给出了跨期变动。"""
        if ctx.result.get("status") not in {"unsupported", "unavailable"}:
            return False
        return _contains_any(ctx.narrative, ("无法展示当期相对基期的变动", "无法展示跨期变动"))

    def _unsupported_forecast_or_risk_link(ctx: GuardContext) -> bool:
        """预测与风险传导不是本工作流能支撑的结论。"""
        return _contains_any(ctx.narrative, FORECAST_OR_RISK_LINK)

    def _overview_causality_without_attribution(ctx: GuardContext) -> bool:
        """概览模式没有归因依据，不该出现因果表述。"""
        if ctx.mode != "overview":
            return False
        if (ctx.result.get("attribution") or {}).get("factors"):
            return False
        return _contains_any(ctx.narrative, ("资产端", "负债端", "主要受"))

    def _currency_comparison_overclaim(ctx: GuardContext) -> bool:
        """币种对比不得越界到风险/优先级判断。

        与集中度规则一样做**子句级否定感知**：v2 原实现是纯子串匹配，会把
        "不代表存在合规空间差异" 这种免责说明也判成越界。
        """
        if ctx.mode != "currencyCompare":
            return False
        for term in CURRENCY_COMPARISON_FORBIDDEN:
            if _asserts(term, ctx.narrative, CLAUSE_NEGATIONS, scoped=_clause_before):
                return True
        return False

    def _concentration_overclaim(ctx: GuardContext) -> bool:
        """集中度不足 50% 时不得断言"明显集中"——子句级否定感知。"""
        share = (ctx.result.get("summary") or {}).get("largestBucketSharePct")
        if share is None or share >= 50:
            return False
        for claim in CONCENTRATION_CLAIMS:
            if _asserts(claim, ctx.narrative, CLAUSE_NEGATIONS, scoped=_clause_before):
                return True
        return False

    def _distribution_causality_unsupported(ctx: GuardContext) -> bool:
        """不得由桶规模推断利率因果——句子级否定感知。"""
        for claim in CAUSALITY_CLAIMS:
            if _asserts(claim, ctx.narrative, SENTENCE_NEGATIONS, scoped=_sentence_before):
                return True
        return False

    def _denominator_direction_wrong(ctx: GuardContext) -> bool:
        """分母实际在上升，文案却说"总生息资产规模下降"。"""
        if ctx.mode != "attribution":
            return False
        denominator = next(
            (item for item in ctx.result.get("factors", []) if item.get("factorCode") == "denominator"),
            None,
        )
        if not denominator:
            return False
        rising = denominator.get("currentValue", 0) > denominator.get("baseValue", 0)
        return rising and "总生息资产规模下降" in ctx.narrative

    def _business_scale_mislabeled(ctx: GuardContext) -> bool:
        """重定价规模不是贷款余额/发放额——短距离否定感知。"""
        for claim in SCALE_MISLABELS:
            for match in re.finditer(re.escape(claim), ctx.narrative):
                window = ctx.narrative[max(0, match.start() - 4):match.start()]
                prefix = ctx.narrative[max(0, match.start() - 40):match.start()]
                enumerated_negation = re.search(
                    r"(?:不是|并非|不等于)(?:(?:贷款余额|发放额|资产占比)[或和、])+$", prefix)
                if not any(word in window for word in SCALE_NEGATIONS) and not enumerated_negation:
                    return True
        return False

    @dataclass(frozen=True)
    class SemanticRule:
        code: str
        why: str
        detect: Callable[[GuardContext], bool]
        modes: frozenset[str] | None = None

    RULES: tuple[SemanticRule, ...] = (
        SemanticRule("CONTRADICTORY_IMPACT_SIGN", "说正向影响却带负号", _contradictory_impact_sign),
        SemanticRule("MANAGEMENT_LIMIT_MISLABELED", "内部限额被说成监管限额", _management_limit_mislabeled),
        SemanticRule("AWKWARD_LIMIT_EXCEEDANCE", "『超出距离』语义不成立", _awkward_limit_exceedance),
        SemanticRule("TECHNICAL_METADATA_LEAK", "把数据包/版本/演示标记写进用户文案", _technical_metadata_leak),
        SemanticRule("UNAVAILABLE_RESULT_TECHNICAL_ADVICE", "结果不可用却给运维建议", _unavailable_technical_advice),
        SemanticRule("ATTRIBUTION_UNAVAILABLE_OVERCLAIM", "结果不可用却声称给了跨期变动", _attribution_unavailable_overclaim),
        SemanticRule("UNSUPPORTED_FORECAST_OR_RISK_LINK", "预测或风险传导超出可支撑范围", _unsupported_forecast_or_risk_link),
        SemanticRule("OVERVIEW_CAUSALITY_WITHOUT_ATTRIBUTION", "概览模式出现无依据的因果表述", _overview_causality_without_attribution),
        SemanticRule("CURRENCY_COMPARISON_OVERCLAIM", "币种对比越界到风险/优先级判断", _currency_comparison_overclaim),
        SemanticRule("DISTRIBUTION_CONCENTRATION_OVERCLAIM", "集中度不足却断言明显集中（子句级否定感知）", _concentration_overclaim),
        SemanticRule("DISTRIBUTION_CAUSALITY_UNSUPPORTED", "由桶规模推断利率因果（句子级否定感知）", _distribution_causality_unsupported),
        SemanticRule("DENOMINATOR_DIRECTION_WRONG", "分母在上升却说下降", _denominator_direction_wrong),
        SemanticRule("BUSINESS_REPRICING_SCALE_MISLABELED", "重定价规模被说成贷款余额/发放额", _business_scale_mislabeled),
    )

    RULE_WHY: dict[str, str] = {rule.code: rule.why for rule in RULES}

    def check_overclaims(ctx: GuardContext) -> list[str]:
        """返回越界表述的诊断码；空列表表示没有越界。"""
        return [rule.code for rule in RULES if rule.detect(ctx)]

    from typing import Any

    def _resolve_path(document: dict, path: str) -> Any:
        if not isinstance(path, str) or not path:
            raise KeyError("INVALID_PATH")
        value: Any = document
        for segment in path.split("."):
            if isinstance(value, dict):
                value = value[segment]
            elif isinstance(value, list) and segment.isdigit():
                value = value[int(segment)]
            else:
                raise KeyError(path)
        return value

    def validate_answer(answer: dict, result: dict, *, mode: str | None = None) -> list[str]:
        errors: list[str] = []
        if not isinstance(answer, dict) or not isinstance(answer.get("headline"), str):
            return ["INVALID_ANSWER_SCHEMA"]
        sections = answer.get("sections")
        if not isinstance(sections, list) or not sections:
            errors.append("MISSING_SECTIONS")
        else:
            for section in sections:
                if not isinstance(section, dict) or not isinstance(section.get("text"), str):
                    errors.append("INVALID_SECTION")
                    continue
                if not isinstance(section.get("citations"), list) or not section["citations"]:
                    errors.append("MISSING_CITATIONS")
                    continue
                for path in section["citations"]:
                    try:
                        _resolve_path(result, path)
                    except (KeyError, IndexError, TypeError):
                        errors.append(f"INVALID_CITATION:{path}")
        refs = answer.get("numericRefs")
        if not isinstance(refs, list):
            errors.append("INVALID_NUMERIC_REFS")
        else:
            for ref in refs:
                if not isinstance(ref, dict) or "path" not in ref or "value" not in ref:
                    errors.append("INVALID_NUMERIC_REF")
                    continue
                try:
                    actual = _resolve_path(result, ref["path"])
                except (KeyError, IndexError, TypeError):
                    errors.append(f"INVALID_NUMERIC_PATH:{ref['path']}")
                    continue
                if isinstance(actual, (int, float)) and isinstance(ref["value"], (int, float)):
                    if abs(actual - ref["value"]) > 1e-6:
                        errors.append(f"NUMERIC_MISMATCH:{ref['path']}")
                elif actual != ref["value"]:
                    errors.append(f"VALUE_MISMATCH:{ref['path']}")
        if isinstance(refs, list) and all(isinstance(item, dict) for item in refs):
            source_values = [item.get("value") for item in refs if isinstance(item.get("value"), (int, float))]
            cited_identifiers = []
            if isinstance(sections, list):
                for section in sections:
                    if not isinstance(section, dict) or not isinstance(section.get("citations"), list):
                        continue
                    for path in section["citations"]:
                        try:
                            value = _resolve_path(result, path)
                        except (KeyError, IndexError, TypeError):
                            continue
                        if isinstance(value, str) and any(char.isdigit() for char in value):
                            cited_identifiers.append(value)
            cited_identifiers.extend(collect_identifier_keys(result))
            texts = [answer.get("headline", "")]
            if isinstance(sections, list):
                texts.extend(item["text"] for item in sections
                             if isinstance(item, dict) and isinstance(item.get("text"), str))
            errors.extend(
                find_unreferenced_numbers(
                    texts,
                    source_values=source_values,
                    cited_identifiers=cited_identifiers,
                    compared_currencies=result.get("comparedCurrencies"),
                    cited_paths={item["path"] for item in refs if isinstance(item.get("path"), str)},
                )
            )
        if str(result.get("attributionMethod") or "").startswith("SYNTHETIC"):
            if "百分点" in answer.get("headline", ""):
                errors.append("ILLUSTRATIVE_IMPACT_IN_HEADLINE")
            if isinstance(sections, list):
                for section in sections:
                    if isinstance(section, dict) and "illustrativeImpactPctPoint" in section.get("citations", []):
                        if "演示" not in section.get("text", ""):
                            errors.append("ILLUSTRATIVE_IMPACT_UNLABELED")
        initial_causes = result.get("attribution") or {}
        if mode == "overview" and initial_causes.get("factors"):
            paths = {r.get("path") for r in refs if isinstance(r, dict)} if isinstance(refs, list) else set()
            if "attribution.changePctPoint" not in paths:
                errors.append("INITIAL_CAUSES_MISSING")
            cause_sections = [s for s in sections if isinstance(s, dict) and any(
                str(p).startswith("attribution.") for p in s.get("citations", []) or [])] if isinstance(sections, list) else []
            if not cause_sections:
                errors.append("INITIAL_CAUSES_MISSING")
            if str(initial_causes.get("method", "")).startswith("SYNTHETIC"):
                if any("演示" not in s.get("text", "") for s in cause_sections):
                    errors.append("DEMO_ATTRIBUTION_UNLABELED")
        if mode == "attribution" and str(result.get("method", "")).startswith("SYNTHETIC"):
            if isinstance(sections, list) and any(isinstance(s, dict) and "演示" not in s.get("text", "")
                    for s in sections if isinstance(s, dict) and isinstance(s.get("citations"), list) and
                        any(p in ("changePctPoint", "factors") or str(p).startswith("factors.") for p in s["citations"])):
                errors.append("DEMO_ATTRIBUTION_UNLABELED")
        modules = result.get("analyses")
        if isinstance(modules, dict):
            for need in result.get("dataNeeds", []):
                module = modules.get(need)
                if not isinstance(module, dict):
                    errors.append("MISSING_REQUESTED_ANALYSIS:" + str(need))
                    continue
                parts = module.get("byCurrency", [module])
                for index, part in enumerate(parts):
                    prefix = "analyses." + need + (".byCurrency." + str(index) if "byCurrency" in module else "") + "."
                    selected = [s for s in sections if isinstance(s, dict) and isinstance(s.get("citations"), list) and any(
                        isinstance(p, str) and p.startswith(prefix) for p in s["citations"])] if isinstance(sections, list) else []
                    if not selected:
                        errors.append("UNANSWERED_DATA_NEED:" + prefix[:-1])
                        continue
                    sub = {"headline": "", "sections": [{**s, "citations": [p[len(prefix):] for p in s["citations"]
                        if isinstance(p, str) and p.startswith(prefix)]} for s in selected],
                        "numericRefs": [{**r, "path": r["path"][len(prefix):]} for r in refs
                            if isinstance(r, dict) and isinstance(r.get("path"), str) and r["path"].startswith(prefix)] if isinstance(refs, list) else []}
                    errors.extend(prefix + error for error in validate_answer(sub, part, mode=need))
                    errors.extend(prefix + error for error in check_overclaims(
                        GuardContext(mode=need, result=part, narrative=answer.get("headline", ""))))
                    paths = {r["path"] for r in sub["numericRefs"]}
                    citations = {p for s in sub["sections"] for p in s["citations"]}
                    if part.get("status") == "available":
                        required = {
                            "limit": "current.value", "attribution": "changePctPoint",
                            "calculation": "node.value", "business": "changeAmount",
                        }.get(need)
                        missing = required is not None and required not in paths
                        if need == "trend":
                            missing = not any(p.startswith("trend.") and p.endswith(".value") for p in paths)
                        if need == "methodology":
                            missing = not (citations.intersection({"formula", "gapFormula", "exclusions"}) or
                                any(p.startswith("exclusions.") for p in citations))
                        if need == "currencyCompare":
                            missing = any("currencySummary." + str(i) + ".ratio" not in paths
                                for i in range(len(part.get("currencySummary", []))))
                        if need == "attribution":
                            missing = missing or not any(p.startswith("factors.") and p.endswith(".impactPctPoint") for p in paths)
                        if missing:
                            errors.append("INSUFFICIENT_ANALYSIS_EVIDENCE:" + prefix[:-1])
        # 语义越界门禁：数字有据不代表说法成立（"监管限额""美元风险更高"）。
        # 给了 mode 才检查——脱离模式的规则会把合法的免责说明也误杀。
        if mode is not None:
            narrative = "\n".join(
                [answer.get("headline", "")]
                + [item["text"] for item in (sections if isinstance(sections, list) else [])
                   if isinstance(item, dict) and isinstance(item.get("text"), str)]
            )
            errors.extend(check_overclaims(GuardContext(mode="compound" if modules else mode, result=result, narrative=narrative)))
        return errors

    import json
    raw = params.get("narrativeRaw")
    data = params.get("resultPackage") or {}
    mode = params.get("analysisMode")
    errors = []
    try:
        if not isinstance(raw, str):
            raise ValueError("INVALID_JSON")
        cleaned = raw.strip().removeprefix("```json").removesuffix("```").strip()
        answer = normalize_model_answer(json.loads(cleaned))
    except (TypeError, ValueError):
        answer = None
        errors.append("INVALID_JSON")
    if not isinstance(mode, str) or not mode:
        errors.append("MISSING_ANALYSIS_MODE")
    errors.extend(validate_answer(answer, data, mode=mode))
    retry = bool(params.get("isRetry"))
    return {
        "narrative": answer if not errors else None,
        "validationErrors": errors,
        "degradeFlags": ["LIVE_MODEL_OUTPUT_INVALID"] if errors and retry else [],
    }
